e('ata','Anti-topoisomerase I antibodies','antibody','ATA / Scl-70: autoantibodies used for phenotypic stratification; pathogenicity is not established by clinical association.',['ATA','anti-Scl-70'])
e('ara','Anti-RNA polymerase III antibodies','antibody','ARA: autoantibodies associated with diffuse skin involvement and renal crisis; not a proven direct cause of these outcomes.',['ARA','anti-RNAP III'])
e('ssc-ic','SSc autoantibody immune complexes','immune_complex','Experimentally precipitated serum immune complexes; autoantibody group and nucleic-acid cargo affect responses.')
e('pdc','Plasmacytoid dendritic cells','cell','Innate immune cells studied in SSc skin/blood and experimental systems.',['pDC'])
e('cxcl4','CXCL4 (platelet factor 4)','cytokine','Chemokine with a demonstrated capacity to organize DNA and amplify innate sensing.',['PF4'])
