e('pdgf','Platelet-derived growth factor','protein','PDGF ligands involved in fibroblast signalling; isoforms and experimental exposure remain study-specific.',['PDGF'])
e('endothelial','Endothelial cells','cell','HUVECs in the immune-complex experiments; not an assumption of equivalent renal endothelial responses.')
e('et1','Endothelin-1','protein','Vasoactive mediator measured in stimulated cultures.',['ET-1'])
e('il6','IL-6','cytokine','Cytokine studied through trans-signalling and trial-specific receptor blockade.')
e('stat3','JAK / STAT3 signalling','process','IL-6 trans-signalling-associated pathway; no universal pathway sufficiency is asserted.')
e('tgfb','TGF-beta','cytokine','Profibrotic growth-factor signalling; individual isoforms and perturbations remain explicit.',['TGF-β'])
e('smad3','SMAD3 signalling','process','Downstream mediator in the IL-6 / TGF-beta culture model.')
e('fibroblasts','Dermal fibroblasts','cell','Dermal mesenchymal cells across skin cultures and early dcSSc tissue observations.')
e('myofibroblasts','Myofibroblasts','cell','Activated contractile fibroblast phenotype; marker expression alone does not establish lineage.')
