findings=[];receipts=[]
def f(id,key,s,o,p,text,fragment,system,lim,cat='supporting',typ='human_in_vitro',interpret='mechanistic',loc='Primary-report abstract'):
 pmid=bykey[key];pub=pubs[pmid];cache=pub['abstractText'];assert fragment in cache,(id,fragment)
 finding=dict(id='dcssc-'+id,pmid=pmid,subject='entity-'+s,object='entity-'+o,predicate=p,text=text,quote=fragment,quoteLocation=loc,studySystem=system,limitations=[lim],category=cat,evidenceType=typ,causalInterpretation=interpret,sourceCheck=dict(checkedBy='Codex agent source inspection (not independent human review)',checkedAt=date))
 findings.append(finding);receipts.append(dict(findingId=finding['id'],pmid=pmid,checkedBy='Codex agent',checkerKind='agent',checkedAt=date,accessScope=pub['inspectedScope'],sourceUrl='https://pubmed.ncbi.nlm.nih.gov/'+pmid+'/',quote=fragment,location=loc,cachedTextSha256=hashlib.sha256(cache.encode()).hexdigest(),offset=cache.index(fragment),noticeCheck='Europe PMC core publication types, correction/retraction links and notices inspected; no independent publisher-wide notice audit'))
def assoc(id,key,s,o,text,q,sys,lim,cat='supporting'):f(id,key,s,o,'is_associated_with',text,q,sys,lim,cat,'human_observational','association')
